//! The words offered per dialect: its keywords and its built-in functions — the standard's,
//! and SQLite's from `data/sqlite.functions` (generated by `cargo xtask sql-data` from the
//! SQLite the app bundles). Embedded; read on first use into sorted lists pointing into the
//! embedded text, let go when unused for a while (the module's `release_idle`).

use crate::dialect::{Dialect, STANDARD, STANDARD_FUNCTIONS};

static SQLITE_FUNCTIONS: &str = include_str!("../data/sqlite.functions");

/// A built-in function (from the data file).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Function {
    pub name: &'static str,
    /// `s` scalar, `a` aggregate, `w` window (one or more, `,`-separated).
    pub kinds: &'static str,
    /// The argument counts it takes (`-1`: any number), `,`-separated.
    pub arities: &'static str,
}

#[derive(Debug, Default)]
pub struct Words {
    /// Per dialect ([`Dialect::index`]): its keywords and functions, sorted, once each.
    lists: [Vec<&'static str>; 4],
    /// Every dialect's keywords, sorted (a keyword is inserted as one even where it's a
    /// function too: `REPLACE`, `LIKE`).
    keywords: Vec<&'static str>,
    /// Every function name, sorted.
    functions: Vec<&'static str>,
    pub sqlite: Vec<Function>,
}

impl Words {
    /// The heap it takes (its text is the binary's: only the tables).
    pub fn weight(&self) -> u64 {
        use kernel::memory::vec_bytes;
        self.lists.iter().map(vec_bytes).sum::<u64>()
            + vec_bytes(&self.keywords)
            + vec_bytes(&self.functions)
            + vec_bytes(&self.sqlite)
    }

    /// What's offered in `dialect`: its keywords and functions.
    pub fn of(&self, dialect: Dialect) -> &[&'static str] {
        &self.lists[dialect.index()]
    }

    /// `word` (in capitals) is a function and not a keyword of any dialect.
    pub fn is_call(&self, word: &str) -> bool {
        self.functions.binary_search(&word).is_ok() && self.keywords.binary_search(&word).is_err()
    }
}

pub static WORDS: kernel::cache::OnDemand<Words> = kernel::cache::OnDemand::new(load);

pub fn get() -> std::sync::Arc<Words> {
    WORDS.get()
}

/// The data file's functions (comments and malformed lines skipped).
pub fn parse(text: &'static str) -> Vec<Function> {
    text.lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|line| {
            let mut fields = line.split('\t');
            let (name, kinds, arities) = (fields.next()?, fields.next()?, fields.next()?);
            (!name.is_empty()).then_some(Function { name, kinds, arities })
        })
        .collect()
}

fn load() -> Words {
    let sqlite = parse(SQLITE_FUNCTIONS);
    let sorted = |mut words: Vec<&'static str>| {
        words.sort_unstable();
        words.dedup();
        words
    };
    let lists = Dialect::ALL.map(|dialect| {
        let mut words: Vec<&'static str> = STANDARD.to_vec();
        words.extend_from_slice(dialect.own_keywords());
        words.extend_from_slice(STANDARD_FUNCTIONS);
        if dialect == Dialect::Sqlite {
            words.extend(sqlite.iter().map(|f| f.name));
        }
        sorted(words)
    });
    let mut keywords = STANDARD.to_vec();
    for dialect in Dialect::ALL {
        keywords.extend_from_slice(dialect.own_keywords());
    }
    let mut functions = STANDARD_FUNCTIONS.to_vec();
    functions.extend(sqlite.iter().map(|f| f.name));
    Words { lists, keywords: sorted(keywords), functions: sorted(functions), sqlite }
}

